def centroid(man):
    me=man.to_mesh(); v=np.asarray(me.vert_properties,float)[:,:3]; t=np.asarray(me.tri_verts)
    a,b,c=v[t[:,0]],v[t[:,1]],v[t[:,2]]
    vol=np.einsum('ij,ij->i',a,np.cross(b,c))/6.0
    cen=(a+b+c)/4.0
    return (vol[:,None]*cen).sum(0)/vol.sum()

def printable(man):
    h=0.05
    bb=man.bounding_box(); lo=np.array(bb[:3])-0.3; hi=np.array(bb[3:])+0.3
    k0=np.floor((lo-0.0113)/h)
    origin=0.0113+h*k0-0.5*h
    shape=tuple(int(x) for x in np.ceil((hi-origin)/h)+1)
    n,dev=kernel.opening_test_slabs(man,origin,shape,h,1.5,1.0,6.0)
    return n>0 and dev<=4.0+1e-9, dev

